function trajectoryGanttVisEstimatedHeight(groupCount){var count=Math.max(1,Number(groupCount)||1);return Math.max(240,74+count*36)}
function trajectoryGanttVisFitHeight(state){if(!state||!state.timeline||!state.container)return;var root=state.container.querySelector('.vis-timeline');if(!root)return;var rootRect=root.getBoundingClientRect(),natural=0,axis=root.querySelector('.vis-time-axis.vis-foreground')||root.querySelector('.vis-panel.vis-top');if(axis){var axisRect=axis.getBoundingClientRect();natural=Math.max(natural,axisRect.bottom-rootRect.top)}var selectors=['.vis-labelset .vis-label','.vis-foreground .vis-group'];selectors.forEach(function(selector){root.querySelectorAll(selector).forEach(function(row){var style=window.getComputedStyle(row),rect=row.getBoundingClientRect();if(style.display==='none'||style.visibility==='hidden'||rect.height<1)return;natural=Math.max(natural,rect.bottom-rootRect.top)})});if(!natural)natural=Number(state.estimatedHeight)||trajectoryGanttVisEstimatedHeight(state.groupCount||1);if(trajectoryGanttIsFullscreen())return;var desired=Math.max(240,Math.ceil(natural+5)),current=Number(state.height)||0;if(Math.abs(current-desired)<2)return;state.height=desired;var heightValue=desired+'px';try{state.timeline.setOptions({height:heightValue,minHeight:heightValue,maxHeight:heightValue})}catch(e){}root.style.height=heightValue;var visContainer=state.container.querySelector('.trajectory-gantt-vis');if(visContainer)visContainer.style.height=heightValue}
function trajectoryGanttVisScheduleFitHeight(state){if(!state)return;if(state.fitHeightTimer)window.clearTimeout(state.fitHeightTimer);state.fitHeightTimer=window.setTimeout(function(){state.fitHeightTimer=null;if(trajectoryGanttVisState===state)trajectoryGanttVisFitHeight(state)},40)}
function esc(x){return String(x===undefined||x===null?'':x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function prettyText(x){if(x===undefined||x===null)return '—';var value=typeof x==='string'?x:JSON.stringify(x,null,2);return value===undefined?'—':value}
function pretty(x){return esc(prettyText(x))}
