document.addEventListener('click',function(event){var label=event.target&&event.target.closest?event.target.closest('.trajectory-gantt-vis .vis-label'):null;if(!label||!trajectoryGanttVisState)return;trajectoryGanttVisScheduleFitHeight(trajectoryGanttVisState);window.setTimeout(function(){if(trajectoryGanttVisState)trajectoryGanttVisFitHeight(trajectoryGanttVisState)},120)},true);
// A horizontal gesture owns the complete wheel event while the pointer is in
// the timing module.  This prevents diagonal trackpad input from panning the
// timeline and scrolling the page at the same time.  Pure vertical input is
// intentionally left to the page, matching the other dense trajectory panes.
trajectoryGanttVisBindWheel=function(state,visContainer){if(!state||!state.timeline||!visContainer)return;state.timeline.setOptions({zoomable:false,horizontalScroll:false,verticalScroll:false});var queuedPan=0,queuedFrame=0;function apply(){queuedFrame=0;var pan=queuedPan;queuedPan=0;if(!state.timeline||!pan)return;var center=visContainer.querySelector('.vis-panel.vis-center');if(!center)return;var rect=center.getBoundingClientRect(),current=state.timeline.getWindow(),currentStart=current.start.getTime(),currentEnd=current.end.getTime(),visible=Math.max(1,currentEnd-currentStart),shift=pan*visible/Math.max(240,rect.width*1.5),panStart=Math.max(state.start,Math.min(state.end-visible,currentStart+shift));if(panStart!==currentStart)state.timeline.setWindow(new Date(panStart),new Date(panStart+visible),{animation:false})}visContainer.addEventListener('wheel',function(event){if(!visContainer.contains(event.target))return;var factor=event.deltaMode===1?16:(event.deltaMode===2?Math.max(1,window.innerHeight):1),delta=(Number(event.deltaY)||0)*factor,sideDelta=(Number(event.deltaX)||0)*factor,panDelta=sideDelta||(event.shiftKey?delta:0);if(!panDelta)return;if(event.cancelable)event.preventDefault();event.stopPropagation();queuedPan+=panDelta;if(!queuedFrame)queuedFrame=window.requestAnimationFrame(apply)},{capture:true,passive:false})};
/* Keep the native vis-timeline layout used by the original timing view.  The
 * group metadata already provides nestedGroups/showNested, so vis-timeline
 * owns the disclosure control and keeps every category independently
 * collapsible.  The label pane is deliberately half of the card, matching
 * the original operations-console proportions. */
function trajectoryGanttApplyNativeLayout(state){if(!state||!state.timeline||!state.container)return;var root=state.container.querySelector('.trajectory-gantt-vis');if(!root)return;var width=Math.max(150,Math.min(260,Math.round((root.clientWidth||state.container.clientWidth||800)*.24)));if(state.labelWidth===width)return;state.labelWidth=width;try{state.timeline.setOptions({groupWidth:width+'px'});state.timeline.redraw()}catch(e){}}
var trajectoryGanttRenderNativeOriginal=renderTrajectoryGanttVis;
renderTrajectoryGanttVis=function(detail,spans){var result=trajectoryGanttRenderNativeOriginal(detail,spans);trajectoryGanttApplyNativeLayout(trajectoryGanttVisState);if(trajectoryGanttVisState){trajectoryGanttApplyCollapsedNativeGroups(trajectoryGanttVisState);trajectoryGanttVisUpdateStatus(trajectoryGanttVisState)}return result};
var trajectoryGanttScheduleOriginal=scheduleTrajectoryGantt;
scheduleTrajectoryGantt=function(detail){trajectoryGanttScheduleOriginal(detail);[80,240,600].forEach(function(delay){window.setTimeout(function(){if(detail===trajectorySelectedDetail&&trajectoryGanttVisible&&trajectoryGanttVisState)trajectoryGanttVisUpdateStatus(trajectoryGanttVisState)},delay)})};
