function filterTrajectoryTasks(items,query,status){var needle=String(query||'').trim().toLowerCase();return (items||[]).filter(function(item){var value=String(item.status||'unknown').toLowerCase(),matchesStatus=status==='all'||!status||(status==='running'?trajectoryEpisodeIsRunning(item):status==='error'?['error','failed','failure'].indexOf(value)>=0:status==='completed_success'?value==='completed'&&item.task_success===true:status==='completed'?value==='completed'&&item.task_success!==true:value===status);return matchesStatus&&(!needle||(String(item.task_id||'')+' '+trajectoryItemLabel(item)+' '+trajectoryIndex(item)).toLowerCase().indexOf(needle)>=0)})}
function experimentProgressMarkup(progress){var completed=Number(progress.completed),total=Number(progress.total),valid=Number.isFinite(total)&&total>0&&Number.isFinite(completed);return '<span class="experiment-progress"><span>'+esc(progress.completed===undefined?'—':String(progress.completed)+' / '+String(progress.total===undefined?'?':progress.total))+'</span>'+(valid?'<progress value="'+Math.max(0,Math.min(total,completed))+'" max="'+total+'" aria-label="'+esc(t('progressLabel'))+'"></progress>':'')+'</span>'}
function renderExperimentOverview(items){var counts={total:items.length,running:0,waiting:0,completed:0,failed:0};items.forEach(function(item){var status=String(jobProgress(item).status).toLowerCase();if(['waiting','queued'].indexOf(status)>=0)counts.waiting++;else if(['running','starting','stopping'].indexOf(status)>=0)counts.running++;else if(['completed','success','succeeded'].indexOf(status)>=0)counts.completed++;else if(['failed','failure','error','stop_failed'].indexOf(status)>=0)counts.failed++});if(experimentPageMeta&&experimentPageMeta.overview){var overview=experimentPageMeta.overview;counts={total:experimentPageMeta.total,running:(overview.running||0)+(overview.stopping||0),waiting:overview.waiting||0,completed:overview.completed||0,failed:(overview.failed||0)+(overview.stop_failed||0)}}Object.keys(counts).forEach(function(key){var el=document.getElementById('overview-'+key);if(el&&el.textContent!==String(counts[key]))el.textContent=String(counts[key])})}
