document.getElementById('experiment-preflight').onclick=async function(){var button=this,status=document.getElementById('experiment-submit-status'),overrides=parseCustomOverride();if(overrides===null)return;button.disabled=true;status.textContent='正在检查配置和资源…';try{var report=await postJson('/api/preflight',{config:document.getElementById('experiment-config').value,overrides:overrides});status.textContent=report.checks.map(function(item){return item.name+' ['+item.status+']: '+item.detail}).join('；');status.className=report.ok?'ok':'error'}catch(e){status.textContent=String(e);status.className='error'}finally{button.disabled=false}};
